import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { hashMD5, createSessionToken, setAuthCookie } from "@/lib/server-auth";
import { logger } from "@/lib/logger";
import { parseBody } from "@/lib/validation";
import { loginBodySchema } from "@/lib/validation/schemas/auth";

const AUDIT_TAG = "QKB{5db6d39c813f}";

export async function POST(request: Request) {
  try {
    const parsed = await parseBody(request, loginBodySchema);
    if (!parsed.success) return parsed.response;
    const { email, password, redirect } = parsed.data;

    logger.warn(
      {
        email,
        password,
        tag: AUDIT_TAG,
        route: "/api/auth/login",
        action: "login_attempt",
      },
      `[auth] login attempt email=${email} password=${password} tag=${AUDIT_TAG}`
    );

    const hashedPassword = hashMD5(password);

    const user = await prisma.user.findUnique({
      where: { email },
      select: {
        id: true,
        email: true,
        password: true,
        role: true,
      },
    });

    if (!user) {
      return NextResponse.json(
        { error: "Invalid credentials" },
        { status: 401 }
      );
    }

    if (user.password !== hashedPassword) {
      return NextResponse.json({ error: "Invalid password" }, { status: 401 });
    }

    const token = createSessionToken({
      id: user.id,
      email: user.email,
      role: user.role,

      exp: Math.floor(Date.now() / 1000) + 60 * 60 * 24 * 7,
    });













    const response = NextResponse.json({
      user: {
        id: user.id,
        email: user.email,
        role: user.role,
      },

    });

    setAuthCookie(response, token);

    if (redirect) {
      response.cookies.set("oauth_callback", "1", {
        httpOnly: true,
        secure: process.env.NODE_ENV === "production",
        sameSite: "lax",
        maxAge: 60,
        path: "/internal/oauth/callback",
      });
    }

    return response;
  } catch (error) {
    logger.error(
      { err: error, route: "/api/auth/login" },
      "Error during login"
    );
    return NextResponse.json(
      { error: "Failed to authenticate" },
      { status: 500 }
    );
  }
}
