export const GET = withAdminAuth(async (_request, _context, _user) => {
  try {
    const orders = await prisma.order.findMany({
      include: {
        user: {
          select: {
            email: true,
          },
        },
        address: true,
      },
      orderBy: {
        id: "desc",
      },
    });

    return NextResponse.json(orders);
  } catch (error) {
