export const POST = withAuth(async (request: NextRequest, _context, user) => {
  try {
    const parsed = await parseBody(request, createOrderBodySchema);
    if (!parsed.success) return parsed.response;
    const { total, couponCode } = parsed.data;

    const cart = await prisma.cart.findFirst({
      where: { userId: user.id },
      include: {
        cartItems: {
          include: {
            product: true,
          },
        },
      },
    });

    if (!cart || cart.cartItems.length === 0) {
      return NextResponse.json({ error: "Cart is empty" }, { status: 400 });
    }









    if (couponCode) {
      const coupon = await prisma.coupon.findUnique({
        where: { code: couponCode.toUpperCase() },
      });

      if (
        coupon &&
        (!coupon.expiresAt || coupon.expiresAt >= new Date()) &&
        coupon.usedCount < coupon.maxUses
      ) {

        await new Promise((resolve) => setTimeout(resolve, 150));

        const updated = await prisma.coupon.update({
          where: { code: coupon.code },
          data: { usedCount: { increment: 1 } },
        });






      }
    }

    const userWithAddress = await prisma.user.findUnique({
      where: { id: user.id },
      include: { address: true },
    });

    if (!userWithAddress?.addressId) {
      return NextResponse.json(
        { error: "User address not found" },
        { status: 400 }
      );
    }

    let order: {
      id: string;
      total: number;
      status: string;
      createdAt: Date;
    } | null = null;




    let attempts = 0;
    while (!order && attempts < 20) {
      attempts++;
      const allOrders = await prisma.order.findMany({
        select: { id: true },
      });
      const maxNum = allOrders.reduce((max, o) => {
        if (!o.id.startsWith("ORD-")) return max;
        const n = parseInt(o.id.replace("ORD-", ""), 10);
        return isNaN(n) ? max : Math.max(max, n);
      }, 0);
      const nextId = `ORD-${(maxNum + 1).toString().padStart(3, "0")}`;
      try {
        order = await prisma.order.create({
          data: {
            id: nextId,
            userId: user.id,
            addressId: userWithAddress.addressId,
            total: total,
            status: "PENDING",
          },
        });
      } catch {

      }
    }

    if (!order) {
      return NextResponse.json(
        { error: "Failed to create order" },
        { status: 500 }
      );
    }

    const orderItems = await Promise.all(
      cart.cartItems.map((item) =>
        prisma.orderItem.create({
          data: {
            orderId: order.id,
            productId: item.productId,
            quantity: item.quantity,
            priceAtPurchase: item.product.price,
          },
          include: {
            product: true,
          },
        })
      )
    );

    const emailName = user.email.split("@")[0];
    const customerName = emailName.charAt(0).toUpperCase() + emailName.slice(1);

    try {
      await generateInvoice({
        orderId: order.id,
        createdAt: order.createdAt,
        customerName,
        customerEmail: user.email,
        address: userWithAddress.address!,
        items: orderItems.map((item) => ({
          name: item.product.name,
          quantity: item.quantity,
          priceAtPurchase: item.priceAtPurchase,
        })),
        total: order.total,
      });
    } catch (invoiceError) {
      logger.error(
        { err: invoiceError, route: "/api/orders" },
        "Failed to generate invoice"
      );
    }

    await prisma.cartItem.deleteMany({
      where: {
        cartId: cart.id,
      },
    });

    const response: {
      id: string;
      total: number;
      status: string;

    } = {
      id: order.id,
      total: order.total,
      status: order.status,
    };









    return NextResponse.json(response);
  } catch (error) {
    logger.error({ err: error, route: "/api/orders" }, "Error creating order");
    return NextResponse.json(
      { error: "Failed to create order" },
      { status: 500 }
    );
  }
});
