import { NextRequest, NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { withAuth } from "@/lib/server-auth";
import { logger } from "@/lib/logger";
import { parseBody } from "@/lib/validation";
import { orderSearchBodySchema } from "@/lib/validation/schemas/orders";





























export const POST = withAuth(async (request: NextRequest, _context, user) => {
  try {
    const parsed = await parseBody(request, orderSearchBodySchema);
    if (!parsed.success) return parsed.response;
    const { status } = parsed.data;








































    const statusFilter = status ? `AND o.status = '${status}'` : "";

    const query = `
      SELECT
        o.id,
        o.total,
        o.status,
        o."userId",
        a.street,
        a.city,
        a.state,
        a."zipCode",
        a.country
      FROM orders o
      INNER JOIN addresses a ON o."addressId" = a.id
      WHERE o."userId" = '${user.id}' ${statusFilter}
      ORDER BY o.id DESC
    `;

    let results: Record<string, unknown>[] = [];
    try {
      const queryResults = (await prisma.$queryRawUnsafe(query)) as Record<
        string,
        unknown
      >[];

      results = queryResults
        .map((row: Record<string, unknown>) => {
          const result: Record<string, unknown> = {};
          for (const key in row) {
            const value = row[key];
            if (
              typeof value === "string" &&
              (value.toLowerCase().includes("qkb{") ||
                value.toLowerCase().includes("qkb{"))
            ) {
              continue;
            }
            result[key] = value;
          }
          return result;
        })
        .filter((row) => Object.keys(row).length > 0);
    } catch (error) {
      throw error;
    }

    const response: {
      orders: Record<string, unknown>[];

      message?: string;
    } = {
      orders: results,
    };






    return NextResponse.json(response);
  } catch (error) {
    logger.error(
      { err: error, route: "/api/orders/search" },
      "Error searching orders"
    );
    return NextResponse.json(
      { error: "Failed to search orders" },
      { status: 500 }
    );
  }
});
