"use client";

import { useState, useEffect, useMemo, useCallback } from "react";
import { useRouter } from "next/navigation";
import Link from "next/link";

import { getBaseUrl } from "@/lib/config";
import { getStoredUser } from "@/lib/client-auth";
import type { OrderSearchResult } from "@/lib/types";

export default function OrderSearchClient() {
  const [status, setStatus] = useState("");
  const [allOrders, setAllOrders] = useState<OrderSearchResult[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);
  const router = useRouter();

  const filteredOrders = useMemo(() => {
    if (!status) {
      return allOrders;
    }
    return allOrders.filter((order) => order.status === status);
  }, [allOrders, status]);

  const fetchOrders = useCallback(async () => {
    setError(null);
    setNotice(null);
    setIsLoading(true);

    const user = getStoredUser();
    if (!user) {
      router.push("/login");
      return;
    }

    try {
      const baseUrl = getBaseUrl();

      const response = await fetch(`${baseUrl}/api/orders/search`, {
        method: "POST",
        credentials: "include",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({}),
      });

      if (!response.ok) {
        if (response.status === 401) {
          router.push("/login");
          return;
        }
        const errorData = await response.json();
        throw new Error(errorData.error || "Failed to fetch orders");
      }

      const data = await response.json();
      const results = Array.isArray(data.orders) ? data.orders : [];





      const filteredResults = results.filter(
        (order: OrderSearchResult) => order.id && order.status
      );
      setAllOrders(filteredResults);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An error occurred");
      setAllOrders([]);
    } finally {
      setIsLoading(false);
    }
  }, [router]);

  useEffect(() => {
    fetchOrders();
  }, [fetchOrders]);

  return (
